        discountedAmount {
          ...MoneyFragment
          __typename
        }
        __typename
      }
      __typename
    }
    lineItems {
      ...LineItemFragment_Cart
      __typename
    }
    shippingAddress {
      ...AddressFragment
      __typename
    }
    discountCodes {
      ...DiscountCodeFragment
      __typename
    }
    shippingInfo {
      shippingMethodName
      price {
        ...MoneyFragment
        __typename
      }
      taxRate {
        includedInPrice
        __typename
      }
      discountedPrice {
        value {
          ... on Money {
            ...MoneyFragment
            __typename
          }
          __typename
